   102→public class DashboardController extends BaseController {
   103→
   104→    private final TbDashboardService tbDashboardService;
   105→    private final TbResourceService tbResourceService;
   106→
   107→    public static final String DASHBOARD_ID = "dashboardId";
   108→    private static final String HOME_DASHBOARD_ID = "homeDashboardId";
   109→    private static final String HOME_DASHBOARD_HIDE_TOOLBAR = "homeDashboardHideToolbar";
   110→    public static final String DASHBOARD_INFO_DEFINITION = "The Dashboard Info object contains lightweight information about the dashboard (e.g. title, image, assigned customers) but does not contain the heavyweight configuration JSON.";
   111→    public static final String DASHBOARD_DEFINITION = "The Dashboard object is a heavyweight object that contains information about the dashboard (e.g. title, image, assigned customers) and also configuration JSON (e.g. layouts, widgets, entity aliases).";
   112→    public static final String HIDDEN_FOR_MOBILE = "Exclude dashboards that are hidden for mobile";
