   117→    @ApiOperation(value = "Get server time (getServerTime)",
   118→            notes = "Get the server time (milliseconds since January 1, 1970 UTC). " +
   119→                    "Used to adjust view of the dashboards according to the difference between browser and server time.")
   120→    @PreAuthorize("hasAnyAuthority('SYS_ADMIN', 'TENANT_ADMIN', 'CUSTOMER_USER')")
   121→    @GetMapping(value = "/dashboard/serverTime")
   122→    @ApiResponse(responseCode = "200", description = "OK", content = @Content(schema = @Schema(type = "integer", format = "int64", example = "1636023857137")))
   123→    public long getServerTime() {
   124→        return System.currentTimeMillis();
   125→    }
   126→
   127→    @ApiOperation(value = "Get max data points limit (getMaxDatapointsLimit)",
   128→            notes = "Get the maximum number of data points that dashboard may request from the server per in a single subscription command. " +
   129→                    "This value impacts the time window behavior. It impacts 'Max values' parameter in case user selects 'None' as 'Data aggregation function'. " +
   130→                    "It also impacts the 'Grouping interval' in case of any other 'Data aggregation function' is selected. " +
   131→                    "The actual value of the limit is configurable in the system configuration file.")
   132→    @PreAuthorize("hasAnyAuthority('SYS_ADMIN', 'TENANT_ADMIN', 'CUSTOMER_USER')")
   133→    @GetMapping(value = "/dashboard/maxDatapointsLimit")
   134→    @ApiResponse(responseCode = "200", description = "OK", content = @Content(schema = @Schema(type = "integer", format = "int64", example = "5000")))
   135→    public long getMaxDatapointsLimit() {
   136→        return maxDatapointsLimit;
   137→    }
