   139→    @ApiOperation(value = "Get Dashboard Info (getDashboardInfoById)",
   140→            notes = "Get the information about the dashboard based on 'dashboardId' parameter. " + DASHBOARD_INFO_DEFINITION)
   141→    @PreAuthorize("hasAnyAuthority('SYS_ADMIN', 'TENANT_ADMIN', 'CUSTOMER_USER')")
   142→    @GetMapping(value = "/dashboard/info/{dashboardId}")
   143→    public DashboardInfo getDashboardInfoById(
   144→            @Parameter(description = DASHBOARD_ID_PARAM_DESCRIPTION)
   145→            @PathVariable(DASHBOARD_ID) String strDashboardId) throws ThingsboardException {
   146→        checkParameter(DASHBOARD_ID, strDashboardId);
   147→        DashboardId dashboardId = new DashboardId(toUUID(strDashboardId));
   148→        return checkDashboardInfoId(dashboardId, Operation.READ);
   149→    }
   150→
   151→    @ApiOperation(value = "Get Dashboard (getDashboardById)",
   152→            notes = "Get the dashboard based on 'dashboardId' parameter. " + DASHBOARD_DEFINITION + TENANT_OR_CUSTOMER_AUTHORITY_PARAGRAPH
   153→    )
   154→    @PreAuthorize("hasAnyAuthority('TENANT_ADMIN', 'CUSTOMER_USER')")
   155→    @GetMapping(value = "/dashboard/{dashboardId}")
   156→    public void getDashboardById(@Parameter(description = DASHBOARD_ID_PARAM_DESCRIPTION)
   157→                                 @PathVariable(DASHBOARD_ID) String strDashboardId,
   158→                                 @Parameter(description = INCLUDE_RESOURCES_DESCRIPTION)
   159→                                 @RequestParam(value = INCLUDE_RESOURCES, required = false) boolean includeResources,
   160→                                 @RequestHeader(name = HttpHeaders.ACCEPT_ENCODING, required = false) String acceptEncodingHeader,
   161→                                 HttpServletResponse response) throws Exception {
   162→        checkParameter(DASHBOARD_ID, strDashboardId);
   163→        DashboardId dashboardId = new DashboardId(toUUID(strDashboardId));
   164→        Dashboard dashboard = checkDashboardId(dashboardId, Operation.READ);
   165→        if (includeResources) {
   166→            dashboard.setResources(tbResourceService.exportResources(dashboard, getCurrentUser()));
   167→        }
   168→        response.setContentType(APPLICATION_JSON_VALUE);
   169→        compressResponseWithGzipIFAccepted(acceptEncodingHeader, response, JacksonUtil.writeValueAsBytes(dashboard));
   170→    }
   171→
   172→    @ApiOperation(value = "Create Or Update Dashboard (saveDashboard)",
   173→            notes = "Create or update the Dashboard. When creating dashboard, platform generates Dashboard Id as " + UUID_WIKI_LINK +
   174→                    "The newly created Dashboard id will be present in the response. " +
   175→                    "Specify existing Dashboard id to update the dashboard. " +
   176→                    "Referencing non-existing dashboard Id will cause 'Not Found' error. " +
   177→                    "Remove 'id', 'tenantId' and optionally 'customerId' from the request body example (below) to create new Dashboard entity. " +
   178→                    TENANT_AUTHORITY_PARAGRAPH)
   179→    @ApiResponse(responseCode = "200", description = "OK",
   180→            content = @Content(schema = @Schema(implementation = Dashboard.class)))
   181→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   182→    @PostMapping(value = "/dashboard")
   183→    public void saveDashboard(@io.swagger.v3.oas.annotations.parameters.RequestBody(description = "A JSON value representing the dashboard.")
   184→                              @RequestBody Dashboard dashboard,
   185→                              @RequestHeader(name = HttpHeaders.ACCEPT_ENCODING, required = false) String acceptEncodingHeader,
   186→                              HttpServletResponse response) throws Exception {
   187→        dashboard.setTenantId(getTenantId());
   188→        checkEntity(dashboard.getId(), dashboard, Resource.DASHBOARD);
   189→        var savedDashboard = tbDashboardService.save(dashboard, getCurrentUser());
   190→        response.setContentType(APPLICATION_JSON_VALUE);
   191→        compressResponseWithGzipIFAccepted(acceptEncodingHeader, response, JacksonUtil.writeValueAsBytes(savedDashboard));
   192→    }
   193→
   194→    @ApiOperation(value = "Delete the Dashboard (deleteDashboard)",
   195→            notes = "Delete the Dashboard." + TENANT_AUTHORITY_PARAGRAPH)
   196→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
