   200→        checkParameter(DASHBOARD_ID, strDashboardId);
   201→        DashboardId dashboardId = new DashboardId(toUUID(strDashboardId));
   202→        Dashboard dashboard = checkDashboardId(dashboardId, Operation.DELETE);
   203→        tbDashboardService.delete(dashboard, getCurrentUser());
