   206→    @ApiOperation(value = "Assign the Dashboard (assignDashboardToCustomer)",
   207→            notes = "Assign the Dashboard to specified Customer or do nothing if the Dashboard is already assigned to that Customer. " +
   208→                    "Returns the Dashboard object." + TENANT_AUTHORITY_PARAGRAPH)
   209→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   210→    @PostMapping(value = "/customer/{customerId}/dashboard/{dashboardId}")
   211→    public Dashboard assignDashboardToCustomer(
   212→            @Parameter(description = CUSTOMER_ID_PARAM_DESCRIPTION)
   213→            @PathVariable(CUSTOMER_ID) String strCustomerId,
   214→            @Parameter(description = DASHBOARD_ID_PARAM_DESCRIPTION)
   215→            @PathVariable(DASHBOARD_ID) String strDashboardId) throws ThingsboardException {
   216→        checkParameter(CUSTOMER_ID, strCustomerId);
   217→        checkParameter(DASHBOARD_ID, strDashboardId);
   218→
   219→        CustomerId customerId = new CustomerId(toUUID(strCustomerId));
   220→        Customer customer = checkCustomerId(customerId, Operation.READ);
   221→
   222→        DashboardId dashboardId = new DashboardId(toUUID(strDashboardId));
   223→        Dashboard dashboard = checkDashboardId(dashboardId, Operation.ASSIGN_TO_CUSTOMER);
   224→        return tbDashboardService.assignDashboardToCustomer(dashboard, customer, getCurrentUser());
   225→    }
   226→
   227→    @ApiOperation(value = "Unassign the Dashboard (unassignDashboardFromCustomer)",
   228→            notes = "Unassign the Dashboard from specified Customer or do nothing if the Dashboard is already assigned to that Customer. " +
   229→                    "Returns the Dashboard object." + TENANT_AUTHORITY_PARAGRAPH)
   230→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   231→    @DeleteMapping(value = "/customer/{customerId}/dashboard/{dashboardId}")
   232→    public Dashboard unassignDashboardFromCustomer(
   233→            @Parameter(description = CUSTOMER_ID_PARAM_DESCRIPTION)
   234→            @PathVariable(CUSTOMER_ID) String strCustomerId,
   235→            @Parameter(description = DASHBOARD_ID_PARAM_DESCRIPTION)
   236→            @PathVariable(DASHBOARD_ID) String strDashboardId) throws ThingsboardException {
   237→        checkParameter("customerId", strCustomerId);
   238→        checkParameter(DASHBOARD_ID, strDashboardId);
   239→        CustomerId customerId = new CustomerId(toUUID(strCustomerId));
   240→        Customer customer = checkCustomerId(customerId, Operation.READ);
   241→        DashboardId dashboardId = new DashboardId(toUUID(strDashboardId));
   242→        Dashboard dashboard = checkDashboardId(dashboardId, Operation.UNASSIGN_FROM_CUSTOMER);
   243→        return tbDashboardService.unassignDashboardFromCustomer(dashboard, customer, getCurrentUser());
   244→    }
   245→
   246→    @ApiOperation(value = "Update the Dashboard Customers (updateDashboardCustomers)",
   247→            notes = "Updates the list of Customers that this Dashboard is assigned to. Removes previous assignments to customers that are not in the provided list. " +
   248→                    "Returns the Dashboard object. " + TENANT_AUTHORITY_PARAGRAPH)
   249→
   250→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   251→    @PostMapping(value = "/dashboard/{dashboardId}/customers")
   252→    public Dashboard updateDashboardCustomers(
   253→            @Parameter(description = DASHBOARD_ID_PARAM_DESCRIPTION)
   254→            @PathVariable(DASHBOARD_ID) String strDashboardId,
   255→            @Parameter(description = "JSON array with the list of customer ids, or empty to remove all customers")
   256→            @RequestBody(required = false) String[] strCustomerIds) throws ThingsboardException {
   257→        checkParameter(DASHBOARD_ID, strDashboardId);
   258→        DashboardId dashboardId = new DashboardId(toUUID(strDashboardId));
   259→        Dashboard dashboard = checkDashboardId(dashboardId, Operation.ASSIGN_TO_CUSTOMER);
   260→        Set<CustomerId> customerIds = customerIdFromStr(strCustomerIds);
   261→        return tbDashboardService.updateDashboardCustomers(dashboard, customerIds, getCurrentUser());
   262→    }
   263→
   264→    @ApiOperation(value = "Adds the Dashboard Customers (addDashboardCustomers)",
   265→            notes = "Adds the list of Customers to the existing list of assignments for the Dashboard. Keeps previous assignments to customers that are not in the provided list. " +
   266→                    "Returns the Dashboard object." + TENANT_AUTHORITY_PARAGRAPH)
   267→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   268→    @PostMapping(value = "/dashboard/{dashboardId}/customers/add")
   269→    public Dashboard addDashboardCustomers(
   270→            @Parameter(description = DASHBOARD_ID_PARAM_DESCRIPTION)
   271→            @PathVariable(DASHBOARD_ID) String strDashboardId,
   272→            @Parameter(description = "JSON array with the list of customer ids")
   273→            @RequestBody String[] strCustomerIds) throws ThingsboardException {
   274→        checkParameter(DASHBOARD_ID, strDashboardId);
   275→        DashboardId dashboardId = new DashboardId(toUUID(strDashboardId));
   276→        Dashboard dashboard = checkDashboardId(dashboardId, Operation.ASSIGN_TO_CUSTOMER);
   277→        Set<CustomerId> customerIds = customerIdFromStr(strCustomerIds);
   278→        return tbDashboardService.addDashboardCustomers(dashboard, customerIds, getCurrentUser());
   279→    }
   280→
   281→    @ApiOperation(value = "Remove the Dashboard Customers (removeDashboardCustomers)",
   282→            notes = "Removes the list of Customers from the existing list of assignments for the Dashboard. Keeps other assignments to customers that are not in the provided list. " +
   283→                    "Returns the Dashboard object." + TENANT_AUTHORITY_PARAGRAPH)
   284→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   285→    @PostMapping(value = "/dashboard/{dashboardId}/customers/remove")
   286→    public Dashboard removeDashboardCustomers(
   287→            @Parameter(description = DASHBOARD_ID_PARAM_DESCRIPTION)
   288→            @PathVariable(DASHBOARD_ID) String strDashboardId,
   289→            @Parameter(description = "JSON array with the list of customer ids")
   290→            @RequestBody String[] strCustomerIds) throws ThingsboardException {
   291→        checkParameter(DASHBOARD_ID, strDashboardId);
   292→        DashboardId dashboardId = new DashboardId(toUUID(strDashboardId));
   293→        Dashboard dashboard = checkDashboardId(dashboardId, Operation.UNASSIGN_FROM_CUSTOMER);
   294→        Set<CustomerId> customerIds = customerIdFromStr(strCustomerIds);
   295→        return tbDashboardService.removeDashboardCustomers(dashboard, customerIds, getCurrentUser());
   296→    }
