   298→    @ApiOperation(value = "Assign the Dashboard to Public Customer (assignDashboardToPublicCustomer)",
   299→            notes = "Assigns the dashboard to a special, auto-generated 'Public' Customer. Once assigned, unauthenticated users may browse the dashboard. " +
   300→                    "This method is useful if you like to embed the dashboard on public web pages to be available for users that are not logged in. " +
   301→                    "Be aware that making the dashboard public does not mean that it automatically makes all devices and assets you use in the dashboard to be public." +
   302→                    "Use [assign Asset to Public Customer](#!/asset-controller/assignAssetToPublicCustomerUsingPOST) and " +
   303→                    "[assign Device to Public Customer](#!/device-controller/assignDeviceToPublicCustomerUsingPOST) for this purpose. " +
   304→                    "Returns the Dashboard object." + TENANT_AUTHORITY_PARAGRAPH)
   305→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   306→    @PostMapping(value = "/customer/public/dashboard/{dashboardId}")
   307→    public Dashboard assignDashboardToPublicCustomer(
   308→            @Parameter(description = DASHBOARD_ID_PARAM_DESCRIPTION)
   309→            @PathVariable(DASHBOARD_ID) String strDashboardId) throws ThingsboardException {
   310→        checkParameter(DASHBOARD_ID, strDashboardId);
   311→        DashboardId dashboardId = new DashboardId(toUUID(strDashboardId));
   312→        Dashboard dashboard = checkDashboardId(dashboardId, Operation.ASSIGN_TO_CUSTOMER);
   313→        return tbDashboardService.assignDashboardToPublicCustomer(dashboard, getCurrentUser());
   314→    }
