   318→                    "Returns the Dashboard object." + TENANT_AUTHORITY_PARAGRAPH)
   319→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   320→    @DeleteMapping(value = "/customer/public/dashboard/{dashboardId}")
