   330→    @ApiOperation(value = "Get Tenant Dashboards by System Administrator (getTenantDashboardsByTenantId)",
   331→            notes = "Returns a page of dashboard info objects owned by tenant. " + DASHBOARD_INFO_DEFINITION + " " + PAGE_DATA_PARAMETERS +
   332→                    SYSTEM_AUTHORITY_PARAGRAPH)
   333→    @PreAuthorize("hasAuthority('SYS_ADMIN')")
   334→    @GetMapping(value = "/tenant/{tenantId}/dashboards")
   335→    public PageData<DashboardInfo> getTenantDashboardsByTenantId(
   336→            @Parameter(description = TENANT_ID_PARAM_DESCRIPTION, required = true)
   337→            @PathVariable(TENANT_ID) String strTenantId,
   338→            @Parameter(description = PAGE_SIZE_DESCRIPTION, required = true)
   339→            @RequestParam int pageSize,
   340→            @Parameter(description = PAGE_NUMBER_DESCRIPTION, required = true)
   341→            @RequestParam int page,
   342→            @Parameter(description = DASHBOARD_TEXT_SEARCH_DESCRIPTION)
   343→            @RequestParam(required = false) String textSearch,
   344→            @Parameter(description = SORT_PROPERTY_DESCRIPTION, schema = @Schema(allowableValues = {"createdTime", "title"}))
   345→            @RequestParam(required = false) String sortProperty,
   346→            @Parameter(description = SORT_ORDER_DESCRIPTION, schema = @Schema(allowableValues = {"ASC", "DESC"}))
   347→            @RequestParam(required = false) String sortOrder) throws ThingsboardException {
   348→        TenantId tenantId = TenantId.fromUUID(toUUID(strTenantId));
   349→        checkTenantId(tenantId, Operation.READ);
   350→        PageLink pageLink = createPageLink(pageSize, page, textSearch, sortProperty, sortOrder);
   351→        return checkNotNull(dashboardService.findDashboardsByTenantId(tenantId, pageLink));
   352→    }
