   354→    @ApiOperation(value = "Get Tenant Dashboards (getTenantDashboards)",
   355→            notes = "Returns a page of dashboard info objects owned by the tenant of a current user. "
   356→                    + DASHBOARD_INFO_DEFINITION + " " + PAGE_DATA_PARAMETERS + TENANT_AUTHORITY_PARAGRAPH)
   357→    @PreAuthorize("hasAuthority('TENANT_ADMIN')")
   358→    @GetMapping(value = "/tenant/dashboards")
   359→    public PageData<DashboardInfo> getTenantDashboards(
   360→            @Parameter(description = PAGE_SIZE_DESCRIPTION, required = true)
   361→            @RequestParam int pageSize,
   362→            @Parameter(description = PAGE_NUMBER_DESCRIPTION, required = true)
   363→            @RequestParam int page,
   364→            @Parameter(description = HIDDEN_FOR_MOBILE)
   365→            @RequestParam(required = false) Boolean mobile,
