   438→                Tenant tenant = tenantService.findTenantById(securityUser.getTenantId());
   439→                additionalInfo = tenant.getAdditionalInfo();
   440→                homeDashboard = extractHomeDashboardFromAdditionalInfo(additionalInfo);
   441→            }
   442→        }
