   497→        }
   498→        Tenant tenant = tenantService.findTenantById(getTenantId());
   499→        JsonNode additionalInfo = tenant.getAdditionalInfo();
   500→        if (!(additionalInfo instanceof ObjectNode)) {
   501→            additionalInfo = JacksonUtil.newObjectNode();
   502→        }
   503→        if (homeDashboardInfo.getDashboardId() != null) {
   504→            ((ObjectNode) additionalInfo).put(HOME_DASHBOARD_ID, homeDashboardInfo.getDashboardId().getId().toString());
   505→            ((ObjectNode) additionalInfo).put(HOME_DASHBOARD_HIDE_TOOLBAR, homeDashboardInfo.isHideDashboardToolbar());
